// #db7e39 פעולות מחיקה וביטול — окна подтверждения во вкладках профиля компании (/onboarding, tablist «פרופיל החברה»):
// «הסרת מסמך» (מסמכים קבועים) и «הסרת גורם מקצועי» (גורמים מקצועיים קבועים).
// Кейсы: .qa/tests/confirm-dialogs/CD-02, CD-03. План: specs/confirm-dialogs.md (раздел 2).
// ADMIN2 (компания B). Только свои записи qa-auto-confirm-* / QA-AUTO-confirm-*; чужие файлы компании (qa-dragdrop.pdf,
// qa-dialog.pdf) не трогаются. В finally все такие записи удаляются (с подтверждением). Меняет данные → @data.
import { test, expect, Page } from '@playwright/test';
import { authState, qaFile, uploadItem } from '../helpers/tenderflow';
import { confirmDialog, dismissAllWays, expectConfirmDialog, trackWrites } from './confirm';

const DOCS_TAB = /^מסמכים קבועים/;
const PROS_TAB = /^גורמים מקצועיים קבועים/;
const REMOVE = 'הסרה';
const DOC_DIALOG = 'הסרת מסמך';
const PRO_DIALOG = 'הסרת גורם מקצועי';
const QA_DOC_BUTTONS = /^הסרה: qa-auto-confirm-/i;
const QA_PRO_BUTTONS = /^הסרה: QA-AUTO-confirm-/i;
const stamp = () => `${Date.now()}-${Math.floor(Math.random() * 1000)}`;

/** Профиль компании → вкладка. */
async function openProfileTab(page: Page, tab: RegExp) {
  await page.goto('/onboarding');
  await expect(page.getByRole('tablist', { name: 'פרופיל החברה' })).toBeVisible();
  await page.getByRole('tab', { name: tab }).click();
  await expect(page.getByRole('tab', { name: tab })).toHaveAttribute('aria-selected', 'true');
  await expect(page.getByRole('tabpanel')).toBeVisible();
}

const removeButton = (page: Page, name: string) => page.getByRole('button', { name: `${REMOVE}: ${name}`, exact: true });

/** «הסרה: <name>» → открыто окно подтверждения title. */
async function openRemoveDialog(page: Page, name: string, title: string) {
  await removeButton(page, name).click();
  const dialog = confirmDialog(page, title);
  await expect(dialog).toBeVisible();
  return dialog;
}

/** Очистка: удалить (с подтверждением) все свои записи вкладки, в т.ч. оставшиеся от упавших прогонов. */
async function removeAllQa(page: Page, tab: RegExp, buttons: RegExp, title: string) {
  await openProfileTab(page, tab);
  const leftovers = page.getByRole('button', { name: buttons });
  for (let n = await leftovers.count(); n > 0; n = await leftovers.count()) {
    await leftovers.first().click();
    const dialog = confirmDialog(page, title);
    await expect(dialog).toBeVisible();
    await dialog.getByRole('button', { name: REMOVE, exact: true }).click();
    await expect(dialog).toBeHidden();
    await expect(leftovers).toHaveCount(n - 1);
  }
}

test.use({ storageState: authState('admin2') });

test.describe('חלונות אישור — פרופיל החברה', () => {
  test('הסרת מסמך קבוע: חלון אישור; "חזרה", Escape ולחיצה מחוץ לחלון משאירים את המסמך; "הסרה" מוחקת #db7e39 @desktop @data', async ({ page }) => {
    // CD-02
    const file = qaFile(`qa-auto-confirm-doc-${stamp()}`, 'pdf');
    try {
      await openProfileTab(page, DOCS_TAB);
      await page.getByRole('combobox', { name: 'סוג המסמך להעלאה' }).selectOption({ label: 'מסמך אחר' });
      await page.getByRole('tabpanel').locator('input[type="file"]').setInputFiles(file);
      await expect(uploadItem(page, file.name)).toContainText('הועלה');
      const writes = trackWrites(page);

      // Окно: «להסיר את המסמך «<файл>»? הקובץ יימחק ממסמכי החברה ולא יהיה זמין לשימוש חוזר במכרזים.»
      const text = `להסיר את המסמך «${file.name}»? הקובץ יימחק ממסמכי החברה ולא יהיה זמין לשימוש חוזר במכרזים.`;
      await dismissAllWays(
        page,
        async () => {
          const dialog = await openRemoveDialog(page, file.name, DOC_DIALOG);
          await expectConfirmDialog(dialog, text, REMOVE);
          return dialog;
        },
        async () => {
          await expect(uploadItem(page, file.name)).toHaveCount(1);
        },
      );
      expect(writes, 'отмена окна не отправляет запросов записи').toEqual([]);
      await openProfileTab(page, DOCS_TAB);
      await expect(uploadItem(page, file.name)).toHaveCount(1);

      // «הסרה» — файла нет, и после F5 тоже.
      const dialog = await openRemoveDialog(page, file.name, DOC_DIALOG);
      await dialog.getByRole('button', { name: REMOVE, exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(uploadItem(page, file.name)).toHaveCount(0);
      await openProfileTab(page, DOCS_TAB);
      await expect(removeButton(page, file.name)).toHaveCount(0);
    } finally {
      await removeAllQa(page, DOCS_TAB, QA_DOC_BUTTONS, DOC_DIALOG);
    }
    await expect(page.getByRole('button', { name: QA_DOC_BUTTONS })).toHaveCount(0);
  });

  test('הסרת גורם מקצועי: חלון אישור; "חזרה", Escape ולחיצה מחוץ לחלון משאירים את הגורם; "הסרה" מוחקת #db7e39 @desktop @data', async ({ page }) => {
    // CD-03
    const id = stamp();
    const name = `QA-AUTO-confirm-pro-${id}`;
    const email = `qa-auto-confirm-pro-${id}@example.com`;
    const lawyers = page.getByRole('region', { name: 'עורך דין' }).getByRole('listitem').filter({ hasText: name });
    try {
      await openProfileTab(page, PROS_TAB);
      await page.getByRole('button', { name: 'הוסף עורך דין', exact: true }).click();
      const add = page.getByRole('dialog', { name: 'הוספת גורם מקצועי' });
      await expect(add).toBeVisible();
      await expect(add.getByRole('combobox', { name: 'סוג *' }).locator('option:checked')).toHaveText('עורך דין');
      await add.getByRole('textbox', { name: 'שם *' }).fill(name);
      await add.getByRole('textbox', { name: 'אימייל *' }).fill(email);
      await add.getByRole('button', { name: 'שמירה', exact: true }).click();
      await expect(add).toBeHidden();
      await expect(lawyers).toHaveCount(1);
      await expect(lawyers).toContainText(email);
      const writes = trackWrites(page);

      // Окно: «להסיר את «<имя>» מהגורמים המקצועיים הקבועים?»
      const text = `להסיר את «${name}» מהגורמים המקצועיים הקבועים?`;
      await dismissAllWays(
        page,
        async () => {
          const dialog = await openRemoveDialog(page, name, PRO_DIALOG);
          await expectConfirmDialog(dialog, text, REMOVE);
          return dialog;
        },
        async () => {
          await expect(lawyers).toHaveCount(1);
        },
      );
      expect(writes, 'отмена окна не отправляет запросов записи').toEqual([]);
      await openProfileTab(page, PROS_TAB);
      await expect(lawyers).toHaveCount(1);

      // «הסרה» — специалиста нет, и после F5 тоже.
      const dialog = await openRemoveDialog(page, name, PRO_DIALOG);
      await dialog.getByRole('button', { name: REMOVE, exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(lawyers).toHaveCount(0);
      await openProfileTab(page, PROS_TAB);
      await expect(page.getByRole('button', { name: 'הוסף עורך דין', exact: true })).toBeVisible();
      await expect(page.getByText(name)).toHaveCount(0);
    } finally {
      await removeAllQa(page, PROS_TAB, QA_PRO_BUTTONS, PRO_DIALOG);
    }
    await expect(page.getByRole('button', { name: QA_PRO_BUTTONS })).toHaveCount(0);
  });
});
